<script setup lang="ts">
/**
 * The full view of one entity (`design/archetypes/detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { cloneVNode } from 'vue'

import { definedProps, slottedElements } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/detail-page.module.css'
import Button from '../controls/Button.vue'

export interface DetailPageProps {
  backLabel: string
  /**
   * Keeps the aside in view while the main column scrolls, at the widths where it is beside the
   * main column. It is never taller than the visible box and scrolls inside itself when it is
   * longer. Default `false`: the aside scrolls with the page.
   */
  stickyAside?: boolean
  /**
   * The entity's name, rendered as the page's `<h1>`.
   */
  title: string
}

defineOptions({ name: 'DetailPage', inheritAttrs: false })

withDefaults(defineProps<DetailPageProps>(), { stickyAside: false })
const emit = defineEmits<{ back: [] }>()
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  aside?: (props: Record<string, never>) => unknown
  default?: (props: Record<string, never>) => unknown
  meta?: (props: Record<string, never>) => unknown
  tabs?: (props: Record<string, never>) => unknown
  titleEdit?: (props: Record<string, never>) => unknown
}>()
</script>

<template>
  <div :class="styles.page" data-member="detail-page">
    <!-- back -->
    <div :class="styles.back">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        icon="back"
        :label="backLabel"
        @click="emit('back')"
      />
    </div>
    <!-- header -->
    <div :class="styles.header">
      <!-- identity -->
      <div :class="styles.identity">
        <!-- titleRow -->
        <div v-if="$slots.titleEdit" :class="styles.titleRow">
          <!-- title -->
          <h1 :class="styles.title">
            {{ title }}
          </h1>
          <!-- titleEdit -->
          <div :class="styles.titleEdit">
            <template v-for="(node, at) in slottedElements($slots.titleEdit)" :key="at">
              <component :is="cloneVNode(node, definedProps({ valueHidden: true }))" />
            </template>
          </div>
        </div>
        <!-- title -->
        <h1 v-else :class="styles.title">
          {{ title }}
        </h1>
        <!-- meta -->
        <div v-if="$slots.meta" :class="styles.meta">
          <slot name="meta" />
        </div>
      </div>
      <!-- actions -->
      <div v-if="$slots.actions" :class="styles.actions">
        <slot name="actions" />
      </div>
    </div>
    <slot name="tabs" />
    <!-- body -->
    <div
      v-if="$slots.default || $slots.aside"
      :class="styles.body"
      :data-aside="$slots.aside ? '' : undefined"
      :data-sticky-aside="$slots.aside && stickyAside ? '' : undefined"
    >
      <!-- main -->
      <div :class="styles.main">
        <slot />
      </div>
      <!-- aside -->
      <div v-if="$slots.aside" :class="styles.aside">
        <slot name="aside" />
      </div>
    </div>
  </div>
</template>
